//! End-to-end importer tests against reference outputs of the upstream RVC model.
//!
//! - `test-fixtures/vc/tiny/` (committed, regenerated by
//!   `python scripts/vc-templates/parity_test.py --write-fixture src-tauri/test-fixtures/vc/tiny`):
//!   a random tiny RVC checkpoint in RVC's own format, its templates, and upstream PyTorch outputs
//!   for fixed inputs and noise (`reference.{json,bin}`).
//! - `default_voice_parity` (ignored): the MIT default voice against the bundled v2-40k template;
//!   needs `SIGIL_TEST_MODELS_DIR` with `rvc-default-voice/default.pth` and
//!   `vc-parity/v2-40k-f0-hifigan/reference.*` (written by `parity_test.py`; the dev cache
//!   `%LOCALAPPDATA%\sigil-dev-cache` has this layout).

use std::path::{Path, PathBuf};
use std::time::{Duration, Instant};

use ort::session::Session;
use ort::value::TensorRef;
use sha2::{Digest, Sha256};

use super::session::{template_session, EpTarget, Precision, WeightImages};
use super::*;
use crate::services::neural_audio::ort_session::VcSessionOptions;

// ---- reference bundles (scripts/vc-templates/sigil_layout.py write_bundle) --------------------

pub(super) struct Bundle {
    desc: serde_json::Value,
    bin: Vec<u8>,
}

impl Bundle {
    fn load(stem: &Path) -> Bundle {
        let json = std::fs::read(stem.with_extension("json")).unwrap_or_else(|e| panic!("{}: {e}", stem.display()));
        let bin = std::fs::read(stem.with_extension("bin")).unwrap();
        Bundle { desc: serde_json::from_slice(&json).unwrap(), bin }
    }

    /// The bundle `<stem>.{json,bin}` when both files exist and the description parses.
    pub(super) fn try_load(stem: &Path) -> Option<Bundle> {
        let json = std::fs::read(stem.with_extension("json")).ok()?;
        let bin = std::fs::read(stem.with_extension("bin")).ok()?;
        Some(Bundle { desc: serde_json::from_slice(&json).ok()?, bin })
    }

    fn meta(&self, key: &str) -> &serde_json::Value {
        &self.desc["meta"][key]
    }

    fn entry(&self, name: &str) -> (Vec<usize>, &[u8], String) {
        let t = self.desc["tensors"]
            .as_array()
            .unwrap()
            .iter()
            .find(|t| t["name"] == name)
            .unwrap_or_else(|| panic!("bundle has no {name}"));
        let shape = t["shape"].as_array().unwrap().iter().map(|d| d.as_u64().unwrap() as usize).collect();
        let off = t["offset"].as_u64().unwrap() as usize;
        let len = t["bytes"].as_u64().unwrap() as usize;
        (shape, &self.bin[off..off + len], t["dtype"].as_str().unwrap().to_string())
    }

    fn f32(&self, name: &str) -> (Vec<usize>, Vec<f32>) {
        let (shape, raw, dtype) = self.entry(name);
        assert_eq!(dtype, "float32", "{name}");
        (shape, raw.chunks_exact(4).map(|c| f32::from_le_bytes([c[0], c[1], c[2], c[3]])).collect())
    }

    fn i64(&self, name: &str) -> (Vec<usize>, Vec<i64>) {
        let (shape, raw, dtype) = self.entry(name);
        assert_eq!(dtype, "int64", "{name}");
        (shape, raw.chunks_exact(8).map(|c| i64::from_le_bytes(c.try_into().unwrap())).collect())
    }
}

fn tiny_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("test-fixtures").join("vc").join("tiny")
}

fn bundled_templates() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("resources").join("vc-templates")
}

fn temp_dir(tag: &str) -> PathBuf {
    let d = std::env::temp_dir().join(format!("sigil-vc-import-{tag}-{}", std::process::id()));
    let _ = std::fs::remove_dir_all(&d);
    std::fs::create_dir_all(&d).unwrap();
    d
}

// ---- running the graphs ----------------------------------------------------------------------

fn run_f32(session: &mut Session, feeds: Vec<(&str, Vec<usize>, Vec<f32>)>, ints: Vec<(&str, Vec<usize>, Vec<i64>)>) -> Vec<Vec<f32>> {
    let mut inputs: Vec<(String, ort::session::SessionInputValue<'_>)> = Vec::new();
    for (name, shape, data) in &feeds {
        inputs.push((name.to_string(), TensorRef::from_array_view((shape.clone(), &data[..])).unwrap().into()));
    }
    for (name, shape, data) in &ints {
        inputs.push((name.to_string(), TensorRef::from_array_view((shape.clone(), &data[..])).unwrap().into()));
    }
    let outputs = session.run(inputs).unwrap();
    (0..outputs.len())
        .map(|i| outputs[i].try_extract_tensor::<f32>().unwrap().1.to_vec())
        .collect()
}

/// (max |a - b|, peak |b|)
fn max_abs(a: &[f32], b: &[f32]) -> (f32, f32) {
    assert_eq!(a.len(), b.len(), "length");
    let err = a.iter().zip(b).map(|(x, y)| (x - y).abs()).fold(0f32, f32::max);
    let peak = b.iter().map(|y| y.abs()).fold(0f32, f32::max);
    (err, peak)
}

/// ||a - b|| / ||b|| (the T8 corpus metric).
fn rel_l2(a: &[f32], b: &[f32]) -> f64 {
    let d: f64 = a.iter().zip(b).map(|(x, y)| ((x - y) as f64).powi(2)).sum();
    let n: f64 = b.iter().map(|y| (*y as f64).powi(2)).sum();
    (d / n.max(1e-30)).sqrt()
}

/// Frame-major slice [1, C, T] -> [1, C, T - start] (the last frames).
fn tail_frames(x: &[f32], channels: usize, frames: usize, start: usize) -> Vec<f32> {
    let mut out = Vec::with_capacity(channels * (frames - start));
    for c in 0..channels {
        out.extend_from_slice(&x[c * frames + start..(c + 1) * frames]);
    }
    out
}

struct Parity {
    /// (check, precision, max abs error, tolerance)
    rows: Vec<(String, &'static str, f32, f32)>,
}

impl Parity {
    fn check(&mut self, what: &str, precision: Precision, got: &[f32], want: &[f32], tol: f32, scale_fp16: bool) {
        let (err, peak) = max_abs(got, want);
        let tol = if scale_fp16 && precision == Precision::Fp16 { tol * peak.max(1.0) } else { tol };
        eprintln!(
            "  {:<4} {:<12} {:<5} max|d| {err:.3e} rel_l2 {:.3e} (tol {tol:.3e})",
            if err <= tol { "PASS" } else { "FAIL" },
            what,
            precision.variant(),
            rel_l2(got, want)
        );
        self.rows.push((what.to_string(), precision.variant(), err, tol));
    }

    fn assert_ok(&self) {
        let bad: Vec<_> = self.rows.iter().filter(|r| r.2.is_nan() || r.2 > r.3).collect();
        assert!(bad.is_empty(), "parity failures: {bad:?}");
    }
}

/// Run every check of `parity_test.py` for one precision on `target`.
fn graph_parity(voice: &ImportedVoice, bundle: &Bundle, precision: Precision, target: EpTarget<'_>, parity: &mut Parity, scale_fp16: bool) {
    let layout = &voice.template.layout;
    let tol = match precision {
        Precision::Fp32 => 1e-4,
        Precision::Fp16 => 5e-3,
    };
    let f16 = writer::f16_image(&voice.weights.f32_image).unwrap();
    let images = WeightImages { f32: &voice.weights.f32_image, f16: Some(&f16) };
    let (pshape, phone) = bundle.f32("phone");
    let (_, pitch) = bundle.i64("pitch");
    let frames = pshape[1];
    let emb = pshape[2];
    let c = layout.arch.inter_channels as usize;
    let upp = layout.arch.upp as usize;
    let (fm, dm) = (layout.streaming.flow_margin as usize, layout.streaming.dec_margin as usize);

    let mut enc = template_session(&voice.template, "enc", precision, Some(&images), target, &[("T", frames as i64)]).unwrap();
    let out = run_f32(&mut enc, vec![("phone", vec![1, frames, emb], phone.clone())], vec![("pitch", vec![1, frames], pitch.clone())]);
    let (_, ref_m) = bundle.f32("ref_m_p");
    let (_, ref_logs) = bundle.f32("ref_logs_p");
    parity.check("enc.m_p", precision, &out[0], &ref_m, tol, scale_fp16);
    parity.check("enc.logs_p", precision, &out[1], &ref_logs, tol, scale_fp16);
    let (m_ort, logs_ort) = (out[0].clone(), out[1].clone());

    // Speaker vector from the imported table (row = sid), as the engine computes it.
    let (_, sid) = bundle.i64("sid");
    let dim = voice.weights.speaker_dim;
    let g: Vec<f32> = voice.weights.speakers[sid[0] as usize * dim..(sid[0] as usize + 1) * dim].to_vec();
    let (_, ref_g) = bundle.f32("ref_g");
    assert_eq!(g, ref_g, "speaker vector");

    let (_, f0) = bundle.f32("f0");
    let (_, z_noise) = bundle.f32("z_noise");
    let (_, src_noise) = bundle.f32("src_noise");
    let (_, ref_audio) = bundle.f32("ref_audio");
    let ref_tail = &ref_audio[(fm + dm) * upp..];
    let flowdec_feeds = |m: &[f32], logs: &[f32], start: usize, phase0: f32| {
        let n = frames - start;
        vec![
            ("m_p", vec![1, c, n], tail_frames(m, c, frames, start)),
            ("logs_p", vec![1, c, n], tail_frames(logs, c, frames, start)),
            ("z_noise", vec![1, c, n], tail_frames(&z_noise, c, frames, start)),
            ("g", vec![1, dim, 1], g.clone()),
            ("f0", vec![1, n], f0[start..].to_vec()),
            ("phase0", vec![1, 1], vec![phase0]),
            ("src_noise", vec![1, n * upp], src_noise[start * upp..].to_vec()),
        ]
    };
    let dims = |n: usize| [("F", n as i64), ("S", (n * upp) as i64)];
    let mut fd = template_session(&voice.template, "flowdec", precision, Some(&images), target, &dims(frames)).unwrap();
    let full = run_f32(&mut fd, flowdec_feeds(&ref_m, &ref_logs, 0, 0.0), vec![]).remove(0);
    parity.check("flowdec", precision, &full, ref_tail, tol, scale_fp16);
    let chain = run_f32(&mut fd, flowdec_feeds(&m_ort, &logs_ort, 0, 0.0), vec![]).remove(0);
    parity.check("chain", precision, &chain, ref_tail, tol, scale_fp16);
    if precision == Precision::Fp16 {
        // The recommended GPU mix: enc in fp32 (cheap, and fp16 activations cost it accuracy),
        // flowdec in fp16.
        let mut enc32 = template_session(&voice.template, "enc", Precision::Fp32, Some(&images), target, &[("T", frames as i64)]).unwrap();
        let out = run_f32(&mut enc32, vec![("phone", vec![1, frames, emb], phone.clone())], vec![("pitch", vec![1, frames], pitch.clone())]);
        let mixed = run_f32(&mut fd, flowdec_feeds(&out[0], &out[1], 0, 0.0), vec![]).remove(0);
        parity.check("chain-mixed", precision, &mixed, ref_tail, tol, scale_fp16);
    }

    let start = bundle.meta("partial_start").as_u64().unwrap() as usize;
    let block = bundle.meta("block_frames").as_u64().unwrap() as usize;
    let (_, phase0) = bundle.f32("phase0_partial");
    let mut fdp = template_session(&voice.template, "flowdec", precision, Some(&images), target, &dims(frames - start)).unwrap();
    let part = run_f32(&mut fdp, flowdec_feeds(&ref_m, &ref_logs, start, phase0[0]), vec![]).remove(0);
    assert_eq!(part.len(), block * upp);
    parity.check("partial", precision, &part, &ref_audio[ref_audio.len() - block * upp..], tol, scale_fp16);
    parity.check("partial=full", precision, &part, &full[full.len() - block * upp..], tol, scale_fp16);

    let (qshape, feats) = bundle.f32("knn_feats");
    let (ishape, index) = bundle.f32("knn_index");
    let (_, rate) = bundle.f32("knn_rate");
    let mut knn = template_session(&voice.template, "knn", precision, None, target, &[("T", qshape[0] as i64), ("N", ishape[0] as i64)]).unwrap();
    let got = match precision {
        Precision::Fp32 => {
            let index_sq: Vec<f32> = index.chunks(ishape[1]).map(|r| r.iter().map(|&x| (x as f64) * (x as f64)).sum::<f64>() as f32).collect();
            run_f32(
                &mut knn,
                vec![("feats", qshape.clone(), feats.clone()), ("index", ishape.clone(), index.clone()), ("index_sq", vec![ishape[0]], index_sq), ("index_rate", vec![1], rate.clone())],
                vec![],
            )
            .remove(0)
        }
        Precision::Fp16 => {
            let idx16: Vec<half::f16> = index.iter().map(|&x| half::f16::from_f32(x)).collect();
            let index_sq: Vec<f32> = idx16.chunks(ishape[1]).map(|r| r.iter().map(|x| (x.to_f64()) * x.to_f64()).sum::<f64>() as f32).collect();
            let inputs: Vec<(String, ort::session::SessionInputValue<'_>)> = vec![
                ("feats".into(), TensorRef::from_array_view((qshape.clone(), &feats[..])).unwrap().into()),
                ("index".into(), TensorRef::from_array_view((ishape.clone(), &idx16[..])).unwrap().into()),
                ("index_sq".into(), TensorRef::from_array_view((vec![ishape[0]], &index_sq[..])).unwrap().into()),
                ("index_rate".into(), TensorRef::from_array_view((vec![1usize], &rate[..])).unwrap().into()),
            ];
            let outputs = knn.run(inputs).unwrap();
            outputs[0].try_extract_tensor::<f32>().unwrap().1.to_vec()
        }
    };
    let (_, want) = bundle.f32(if precision == Precision::Fp32 { "knn_ref_fp32" } else { "knn_ref_fp16" });
    parity.check("knn", precision, &got, &want, tol, scale_fp16);
}

/// Relative L2 of a voice's decoded audio against PyTorch's offline output (the T8 corpus metric),
/// with the inputs and noise of a `parity_test.py` reference bundle, decoded on the CPU from the
/// slot's weights image and speaker table as the engine decodes them.
#[derive(Clone, Copy, Debug)]
pub(super) struct ChainRelL2 {
    /// enc fp32 -> flowdec fp32.
    pub fp32: f64,
    /// enc fp16 -> flowdec fp16 (`None`: the weights do not fit half precision).
    pub fp16: Option<f64>,
    /// enc fp32 -> flowdec fp16: what the engine runs for fp16 on a GPU (`layout.json`
    /// `recommended.gpu`; `None` as for `fp16`).
    pub mixed: Option<f64>,
}

/// [`ChainRelL2`] of a voice: `template` with the weights image `weights_f32` and the speaker table
/// `speakers` (`speaker_dim` wide), against `bundle`. Panics on a graph or bundle error (the
/// caller catches it per voice).
pub(super) fn chain_rel_l2(template: &layout::Template, weights_f32: &[u8], speakers: &[f32], speaker_dim: usize, bundle: &Bundle) -> ChainRelL2 {
    let layout = &template.layout;
    let opts = cpu();
    let target = EpTarget::new("cpu", 0, &opts);
    let f16 = writer::f16_image(weights_f32).ok();
    let images = WeightImages { f32: weights_f32, f16: f16.as_deref() };
    let (pshape, phone) = bundle.f32("phone");
    let (_, pitch) = bundle.i64("pitch");
    let (frames, emb) = (pshape[1], pshape[2]);
    let c = layout.arch.inter_channels as usize;
    let upp = layout.arch.upp as usize;
    let (fm, dm) = (layout.streaming.flow_margin as usize, layout.streaming.dec_margin as usize);
    let (_, sid) = bundle.i64("sid");
    let row = sid[0] as usize;
    let g: Vec<f32> = speakers[row * speaker_dim..(row + 1) * speaker_dim].to_vec();
    let (_, f0) = bundle.f32("f0");
    let (_, z_noise) = bundle.f32("z_noise");
    let (_, src_noise) = bundle.f32("src_noise");
    let (_, ref_audio) = bundle.f32("ref_audio");
    let ref_tail = &ref_audio[(fm + dm) * upp..];
    let enc = |precision: Precision| {
        let mut session = template_session(template, "enc", precision, Some(&images), target, &[("T", frames as i64)]).unwrap();
        let mut out = run_f32(&mut session, vec![("phone", vec![1, frames, emb], phone.clone())], vec![("pitch", vec![1, frames], pitch.clone())]);
        let logs = out.pop().unwrap();
        (out.pop().unwrap(), logs)
    };
    let decode = |precision: Precision, m: &[f32], logs: &[f32]| {
        let mut fd = template_session(template, "flowdec", precision, Some(&images), target, &[("F", frames as i64), ("S", (frames * upp) as i64)]).unwrap();
        let feeds = vec![
            ("m_p", vec![1, c, frames], m.to_vec()),
            ("logs_p", vec![1, c, frames], logs.to_vec()),
            ("z_noise", vec![1, c, frames], z_noise.clone()),
            ("g", vec![1, speaker_dim, 1], g.clone()),
            ("f0", vec![1, frames], f0.clone()),
            ("phase0", vec![1, 1], vec![0.0]),
            ("src_noise", vec![1, frames * upp], src_noise.clone()),
        ];
        rel_l2(&run_f32(&mut fd, feeds, vec![]).remove(0), ref_tail)
    };
    let (m32, logs32) = enc(Precision::Fp32);
    let fp32 = decode(Precision::Fp32, &m32, &logs32);
    let (fp16, mixed) = if f16.is_some() {
        let (m16, logs16) = enc(Precision::Fp16);
        (Some(decode(Precision::Fp16, &m16, &logs16)), Some(decode(Precision::Fp16, &m32, &logs32)))
    } else {
        (None, None)
    };
    ChainRelL2 { fp32, fp16, mixed }
}

/// The T8 metric on the tiny fixture: well inside 1e-2 for the engine's fp16 mix.
#[test]
fn tiny_chain_matches_pytorch_within_the_t8_bound() {
    let dir = tiny_dir();
    let voice = import_file(&dir.join("tiny.pth"), &dir).unwrap();
    let bundle = Bundle::load(&dir.join("reference"));
    let r = chain_rel_l2(&voice.template, &voice.weights.f32_image, &voice.weights.speakers, voice.weights.speaker_dim, &bundle);
    eprintln!("tiny chain rel L2: {r:?}");
    assert!(r.fp32 < 1e-4, "{r:?}");
    assert!(r.mixed.unwrap() < 1e-2 && r.fp16.unwrap() < 1e-2, "{r:?}");
}

fn cpu() -> VcSessionOptions {
    VcSessionOptions { intra_threads: Some(2), ..VcSessionOptions::default() }
}

// ---- tiny fixture ----------------------------------------------------------------------------

#[test]
fn tiny_import_is_byte_identical_to_the_python_writer() {
    let dir = tiny_dir();
    let voice = import_file(&dir.join("tiny.pth"), &dir).unwrap();
    assert_eq!(voice.template.layout.template, "v2-16k-f0-hifigan");
    assert_eq!(voice.meta.template_id(), "v2-16k-f0-hifigan");
    let bundle = Bundle::load(&dir.join("reference"));
    assert_eq!(
        hex::encode(Sha256::digest(&voice.weights.f32_image)),
        bundle.meta("weights_f32_sha256").as_str().unwrap(),
        "weights.f32.bin differs from sigil_layout.write_weights"
    );
    let speakers = writer::f32_bytes(&voice.weights.speakers);
    assert_eq!(hex::encode(Sha256::digest(&speakers)), bundle.meta("speakers_f32_sha256").as_str().unwrap());
    assert_eq!(voice.weights.n_speakers as u64, bundle.meta("speakers").as_u64().unwrap());
    assert_eq!(voice.source.kind, "pth");
    assert_eq!(voice.meta.sample_rate, 16_000);
    assert!(voice.meta.warnings.is_empty(), "{:?}", voice.meta.warnings);
}

#[test]
fn tiny_graphs_match_upstream_rvc_on_cpu() {
    let dir = tiny_dir();
    let voice = import_file(&dir.join("tiny.pth"), &dir).unwrap();
    let bundle = Bundle::load(&dir.join("reference"));
    let opts = cpu();
    let target = EpTarget::new("cpu", 0, &opts);
    let mut parity = Parity { rows: Vec::new() };
    graph_parity(&voice, &bundle, Precision::Fp32, target, &mut parity, true);
    graph_parity(&voice, &bundle, Precision::Fp16, target, &mut parity, true);
    parity.assert_ok();
}

#[test]
fn worker_job_writes_the_slot() {
    let dir = tiny_dir();
    let out = temp_dir("worker");
    let job = out.join("job.json");
    std::fs::write(
        &job,
        serde_json::to_vec(&serde_json::json!({
            "version": 1,
            "source": dir.join("tiny.pth"),
            "out_dir": out.join("slot"),
            "templates_dir": dir,
            "time_limit_s": 60,
            "smoke_fp16": true
        }))
        .unwrap(),
    )
    .unwrap();
    let text = run_import_worker(&job).unwrap();
    let record: serde_json::Value = serde_json::from_str(&text).unwrap();
    assert_eq!(record["format"], IMPORT_RECORD_FORMAT);
    assert_eq!(record["checkpoint_dtype"], "float16");
    assert_eq!(record["smoke"].as_array().unwrap().len(), 2, "{text}");
    assert!(record["smoke"][0]["rms"].as_f64().unwrap() > 0.0, "{text}");
    assert_eq!(record["template"], "v2-16k-f0-hifigan");
    assert_eq!(record["fp16_ok"], true);
    let slot = out.join("slot");
    assert!(slot::fp16_checked(&slot), "the fp16 smoke ran: the import cache serves an fp16 request");
    let weights = std::fs::read(slot.join(WEIGHTS_FILE)).unwrap();
    assert_eq!(hex::encode(Sha256::digest(&weights)), record["weights"]["sha256"].as_str().unwrap());
    assert!(slot.join(SPEAKERS_FILE).is_file() && slot.join(IMPORT_RECORD).is_file());
    assert!(!slot.join(format!("{WEIGHTS_FILE}.partial")).exists());

    // Bad jobs fail with a code, never a panic.
    std::fs::write(&job, br#"{"source": "x.pth", "out_dir": "y", "surprise": 1}"#).unwrap();
    assert!(run_import_worker(&job).unwrap_err().starts_with("job:"));
    std::fs::write(&job, serde_json::to_vec(&serde_json::json!({"source": out.join("nope.pth"), "out_dir": slot})).unwrap()).unwrap();
    assert!(run_import_worker(&job).unwrap_err().starts_with("io:"));
    let _ = std::fs::remove_dir_all(&out);
}

#[test]
fn voice_archives_are_unwrapped_and_checked() {
    use std::io::Write as _;
    use zip::write::SimpleFileOptions;
    let dir = tiny_dir();
    let pth = std::fs::read(dir.join("tiny.pth")).unwrap();
    let out = temp_dir("zip");
    let make = |name: &str, files: &[(&str, &[u8])]| -> PathBuf {
        let mut w = zip::ZipWriter::new(std::io::Cursor::new(Vec::new()));
        for (n, d) in files {
            w.start_file(*n, SimpleFileOptions::default().compression_method(zip::CompressionMethod::Deflated)).unwrap();
            w.write_all(d).unwrap();
        }
        let p = out.join(name);
        std::fs::write(&p, w.finish().unwrap().into_inner()).unwrap();
        p
    };
    let ok = make("voice.zip", &[("MyVoice/MyVoice.pth", &pth), ("MyVoice/added_IVF1_Flat_nprobe_1_MyVoice_v2.index", b"idx")]);
    let voice = import_file(&ok, &dir).unwrap();
    assert_eq!(voice.source.kind, "zip");
    assert_eq!(voice.source.pth_entry.as_deref(), Some("MyVoice/MyVoice.pth"));
    assert_eq!(voice.source.index_entries, vec!["MyVoice/added_IVF1_Flat_nprobe_1_MyVoice_v2.index".to_string()]);
    let direct = import_file(&dir.join("tiny.pth"), &dir).unwrap();
    assert_eq!(voice.weights.f32_image, direct.weights.f32_image);

    let two = make("two.zip", &[("a.pth", &pth), ("b.pth", &pth)]);
    assert_eq!(import_file(&two, &dir).err().unwrap().code, ErrorCode::AmbiguousArchive);
    // macOS Finder's "Compress": AppleDouble twins under __MACOSX/ (and a .DS_Store) are ignored.
    let mac = make(
        "mac.zip",
        &[
            ("MyVoice/MyVoice.pth", &pth),
            ("MyVoice/added_IVF1_Flat_nprobe_1_MyVoice_v2.index", b"idx"),
            ("MyVoice/.DS_Store", b"ds"),
            ("__MACOSX/MyVoice/._MyVoice.pth", &[0u8; 4096][..]),
            ("__MACOSX/MyVoice/._added_IVF1_Flat_nprobe_1_MyVoice_v2.index", &[0u8; 4096][..]),
        ],
    );
    let voice = import_file(&mac, &dir).unwrap();
    assert_eq!(voice.source.pth_entry.as_deref(), Some("MyVoice/MyVoice.pth"));
    assert_eq!(voice.source.index_entries, vec!["MyVoice/added_IVF1_Flat_nprobe_1_MyVoice_v2.index".to_string()]);
    let only_metadata = make("metadata.zip", &[("__MACOSX/._voice.pth", &[0u8; 64][..]), ("._voice.pth", &[0u8; 64][..])]);
    assert_eq!(import_file(&only_metadata, &dir).err().unwrap().code, ErrorCode::NotACheckpoint);
    let none = make("none.zip", &[("readme.txt", b"hi")]);
    assert_eq!(import_file(&none, &dir).err().unwrap().code, ErrorCode::NotACheckpoint);
    let evil = make("evil.zip", &[("../../evil.pth", &pth)]);
    assert_eq!(import_file(&evil, &dir).err().unwrap().code, ErrorCode::ArchiveRejected);
    let legacy = out.join("legacy.pth");
    std::fs::write(&legacy, [0x80u8, 0x02, 0x8a, 0x0a, 0x6c, 0xfc]).unwrap();
    assert_eq!(import_file(&legacy, &dir).err().unwrap().code, ErrorCode::LegacyFormat);
    let _ = std::fs::remove_dir_all(&out);
}

