/// Every bundled template either loads (layout version 1) or is refused as a voice kind this build
/// does not run yet (P3-A's version 2: f0-less, MRF and RefineGAN), never as a damaged install.
#[test]
fn bundled_templates_load_or_are_unsupported_voice_kinds() {
    let dir = bundled_templates();
    let (mut v1, mut v2) = (0, 0);
    for entry in std::fs::read_dir(&dir).unwrap().flatten() {
        let id = entry.file_name().to_string_lossy().into_owned();
        if !entry.path().join(layout::LAYOUT_FILE).is_file() {
            continue;
        }
        let raw: serde_json::Value = serde_json::from_slice(&std::fs::read(entry.path().join(layout::LAYOUT_FILE)).unwrap()).unwrap();
        match raw["format_version"].as_u64() {
            Some(1) => {
                layout::Template::load(&dir, &id).unwrap_or_else(|e| panic!("{id}: {}", e.message));
                v1 += 1;
            }
            _ => {
                let e = layout::Template::load(&dir, &id).err().unwrap_or_else(|| panic!("{id} loaded"));
                assert_eq!(e.code, ErrorCode::UnsupportedModel, "{id}: {}", e.message);
                assert!(e.message.contains("not supported yet"), "{id}: {}", e.message);
                v2 += 1;
            }
        }
    }
    assert!(v1 >= 7 && v2 >= 15, "{v1} version-1 and {v2} version-2 templates");
}

#[test]
fn bundled_template_layout_is_valid() {
    let t = layout::Template::load(&bundled_templates(), "v2-40k-f0-hifigan").unwrap();
    let l = &t.layout;
    assert_eq!((l.arch.sample_rate, l.arch.upp, l.arch.emb_channels), (40_000, 400, 768));
    // Every architecture field of RVC's config is compared at import (configs.ARCH_FIELDS):
    // channels, heads, layers, kernel, resblock kernels and dilations, upsample rates and
    // kernels, speaker width, sample rate.
    assert_eq!(l.arch.arch_fields, [2, 3, 4, 5, 6, 7, 9, 10, 11, 12, 13, 14, 16, 17]);
    assert_eq!(l.streaming.flow_margin, 24);
    assert!(l.streaming.dec_margin >= 8 && l.streaming.dec_margin <= 24, "dec margin {}", l.streaming.dec_margin);
    for graph in ["enc", "flowdec", "knn"] {
        for variant in ["fp32", "fp16"] {
            t.graph_bytes(graph, variant).unwrap();
        }
    }
    // The graphs carry no weights: all six stay far below the 30 MB budget for bundled templates.
    let total: u64 = l.graphs.values().flat_map(|g| g.variants.values()).map(|v| v.bytes).sum();
    assert!(total < 2 << 20, "{total} bytes of graphs");
}

/// In-memory weights are copied by ONNX Runtime: the buffer handed to the builder can be freed
/// (and its memory reused) before the session runs.
#[test]
fn in_memory_weights_outlive_their_buffer() {
    let dir = tiny_dir();
    let voice = import_file(&dir.join("tiny.pth"), &dir).unwrap();
    let bundle = Bundle::load(&dir.join("reference"));
    let opts = cpu();
    let target = EpTarget::new("cpu", 0, &opts);
    let image = voice.weights.f32_image.clone();
    let (pshape, phone) = bundle.f32("phone");
    let (_, pitch) = bundle.i64("pitch");
    let mut enc = {
        let images = WeightImages { f32: &image, f16: None };
        template_session(&voice.template, "enc", Precision::Fp32, Some(&images), target, &[]).unwrap()
    };
    drop(image);
    let scribble: Vec<Vec<u8>> = (0..16).map(|i| vec![0xA5u8 ^ i as u8; voice.weights.f32_image.len()]).collect();
    let out = run_f32(&mut enc, vec![("phone", pshape.clone(), phone)], vec![("pitch", vec![1, pshape[1]], pitch)]);
    drop(scribble);
    let (_, ref_m) = bundle.f32("ref_m_p");
    assert!(max_abs(&out[0], &ref_m).0 < 1e-4);
}

